//! Property tests of the model (doc 18 §3.3, §3.5): undo, maintained indexes and load order.
//!
//! The batches are generated by interpretation: proptest draws an abstract plan ([`Action`]s with free
//! selectors) and [`interpret`] turns it into ops against the live model, so every action sees the effects
//! of the ones before it (a delete only names rows that exist, a connection only functions that exist).
//! Everything is deterministic given the plan.

use ew_ids::{Id, Uuid};
use ew_mltext::MlText;
use ew_rds::Aspect;
use ew_schema::{
    Bond, Conductor, Connection, Device, Endpoint, ExternalRef, FnRole, Function, ImportLineage, Junction,
    Kind, LibCopy, Open, Page, PotentialDef, Record, ReportBlock, Representation, Section, StructureNode,
};
use ew_units::{Nm, Pt2};
use proptest::prelude::*;
use serde_json::json;

use super::fixture::{
    DEV_3W1, FNDEF_CONTACT, FNDEF_MCB, PAGE_102, conductor, connection, cp, device, function, mini_golden,
    mini_golden_parts, structure_node,
};
use crate::entity::{AnyKey, table_keys};
use crate::{AnyRow, BaseIndexes, Entity, Model, Op, Rev, invert_batch};

// ---------------------------------------------------------------------------------------------------------
// The abstract plan

/// One abstract edit; the `u32` selectors pick among the rows that exist when the action runs.
#[derive(Clone, Copy, Debug)]
enum Action {
    /// Removes the `(sel % n)`-th table key with the ops of `Model::delete_plan` (skipped if it is refused).
    DeleteViaPlan(u32),
    /// A new location node under `LOC` or under a previously added one.
    AddStructureNode(u32),
    /// A new device and its one main function, in one transaction.
    AddDeviceWithMain(u32),
    /// A new aux function on an existing device that has functions.
    AddAuxFunction(u32),
    /// A new wire between two distinct existing device functions.
    AddConnection(u32, u32, u16, u16),
    /// A new core conductor on the fixture's cable.
    AddConductor(u32),
    /// Changes the function text of an existing device.
    TouchDevice(u32),
    /// Pushes one route point onto an existing connection.
    TouchConnectionRoute(u32),
}

fn action() -> impl Strategy<Value = Action> {
    prop_oneof![
        any::<u32>().prop_map(Action::DeleteViaPlan),
        any::<u32>().prop_map(Action::AddStructureNode),
        any::<u32>().prop_map(Action::AddDeviceWithMain),
        any::<u32>().prop_map(Action::AddAuxFunction),
        (any::<u32>(), any::<u32>(), any::<u16>(), any::<u16>())
            .prop_map(|(a, b, i, j)| Action::AddConnection(a, b, i, j)),
        any::<u32>().prop_map(Action::AddConductor),
        any::<u32>().prop_map(Action::TouchDevice),
        any::<u32>().prop_map(Action::TouchConnectionRoute),
    ]
}

fn batch() -> impl Strategy<Value = Vec<Action>> {
    prop::collection::vec(action(), 1..=6)
}

// ---------------------------------------------------------------------------------------------------------
// The interpreter

/// A fresh ID, unique within a run: the counter is threaded through every batch.
fn fresh<T>(counter: &mut u32) -> Id<T> {
    *counter += 1;
    Id::from_uuid(Uuid::from_u128(0x30_000 + u128::from(*counter)))
}

fn pick<T: Clone>(items: &[T], sel: u32) -> Option<T> {
    (!items.is_empty()).then(|| items[sel as usize % items.len()].clone())
}

/// The ops of one action against `m` (empty if there is nothing to act on).
fn action_ops(m: &Model, action: Action, counter: &mut u32) -> Vec<Op> {
    match action {
        Action::DeleteViaPlan(sel) => {
            let keys = table_keys(m);
            pick(&keys, sel)
                .and_then(|key| m.delete_plan(&key).ok())
                .unwrap_or_default()
        }
        Action::AddStructureNode(sel) => {
            let parents: Vec<Id<StructureNode>> = m
                .table::<StructureNode>()
                .iter()
                .filter(|(_, n)| n.aspect == Open::Known(Aspect::Location))
                .map(|(id, _)| *id)
                .collect();
            let Some(parent) = pick(&parents, sel) else {
                return vec![];
            };
            let id = fresh(counter);
            let node = structure_node(id, Aspect::Location, &format!("N{counter}"), Some(parent));
            vec![Op::insert(AnyRow::of(node))]
        }
        Action::AddDeviceWithMain(sel) => {
            let (did, fid) = (fresh(counter), fresh(counter));
            let letter = ["K", "Q", "S"][sel as usize % 3];
            let dev = device(did, letter, *counter);
            let main = function(fid, did, FNDEF_MCB, FnRole::Main);
            vec![Op::insert(AnyRow::of(dev)), Op::insert(AnyRow::of(main))]
        }
        Action::AddAuxFunction(sel) => {
            let devices: Vec<Id<Device>> = m
                .table::<Function>()
                .iter()
                .filter_map(|(_, f)| f.device)
                .collect();
            let Some(dev) = pick(&devices, sel) else {
                return vec![];
            };
            let aux = function(fresh(counter), dev, FNDEF_CONTACT, FnRole::Aux);
            vec![Op::insert(AnyRow::of(aux))]
        }
        Action::AddConnection(a, b, ia, ib) => {
            let funcs: Vec<Id<Function>> = m
                .table::<Function>()
                .iter()
                .filter(|(_, f)| f.device.is_some())
                .map(|(id, _)| *id)
                .collect();
            if funcs.len() < 2 {
                return vec![];
            }
            let fa = funcs[a as usize % funcs.len()];
            let mut fb = funcs[b as usize % funcs.len()];
            if fa == fb {
                fb = funcs[(b as usize + 1) % funcs.len()];
            }
            let con = connection(
                fresh(counter),
                Some(PAGE_102),
                cp(fa, ia % 4),
                Endpoint::Cp(fb, ib % 4),
            );
            vec![Op::insert(AnyRow::of(con))]
        }
        Action::AddConductor(sel) => {
            if !m.table::<Device>().contains(&DEV_3W1) {
                return vec![];
            }
            let id = fresh(counter);
            let prefix = if sel % 2 == 0 { "N" } else { "C" };
            let cond = conductor(id, DEV_3W1, &format!("{prefix}{counter}"));
            vec![Op::insert(AnyRow::of(cond))]
        }
        Action::TouchDevice(sel) => {
            let devices: Vec<_> = m.table::<Device>().iter().map(|(_, d)| d.clone()).collect();
            let Some(before) = pick(&devices, sel) else {
                return vec![];
            };
            *counter += 1;
            let mut after = (*before).clone();
            after.function_text = MlText::neutral(&format!("T{counter}"));
            vec![Op::update(Device::wrap(before), AnyRow::of(after))]
        }
        Action::TouchConnectionRoute(sel) => {
            let connections: Vec<_> = m.table::<Connection>().iter().map(|(_, c)| c.clone()).collect();
            let Some(before) = pick(&connections, sel) else {
                return vec![];
            };
            *counter += 1;
            let mut after = (*before).clone();
            after.route.push(Pt2::new(
                Nm(1000 * i64::from(*counter)),
                Nm(-1000 * i64::from(*counter)),
            ));
            vec![Op::update(Connection::wrap(before), AnyRow::of(after))]
        }
    }
}

/// Interprets a batch against `start`: each action runs on a scratch model that has applied the actions
/// before it; an action the model rejects is dropped. The result is the op list of the whole batch.
fn interpret(start: &Model, actions: &[Action], counter: &mut u32) -> Vec<Op> {
    let mut scratch = start.clone();
    let mut all = Vec::new();
    for action in actions {
        let ops = action_ops(&scratch, *action, counter);
        if ops.is_empty() {
            continue;
        }
        if let Ok(next) = scratch.apply(&ops, scratch.rev().next()) {
            scratch = next;
            all.extend(ops);
        }
    }
    all
}

/// Interprets a batch on `m` and applies it as the next revision; the batch must apply in one go.
fn step(m: &Model, actions: &[Action], counter: &mut u32) -> (Model, Vec<Op>) {
    let ops = interpret(m, actions, counter);
    let next = m
        .apply(&ops, m.rev().next())
        .unwrap_or_else(|e| panic!("an interpreted batch applies in one transaction: {e:?}"));
    (next, ops)
}

/// The `changed_at` of the row under `key`, `None` if there is none.
fn changed_at(m: &Model, key: &AnyKey) -> Option<Rev> {
    fn of<T: Entity>(m: &Model, key: &AnyKey) -> Option<Rev> {
        m.table::<T>().row(&key.1.cast()).map(|r| r.changed_at())
    }
    match key.0 {
        Kind::ImportLineage => of::<ImportLineage>(m, key),
        Kind::StructureNode => of::<StructureNode>(m, key),
        Kind::Section => of::<Section>(m, key),
        Kind::ExternalRef => of::<ExternalRef>(m, key),
        Kind::Page => of::<Page>(m, key),
        Kind::Device => of::<Device>(m, key),
        Kind::Function => of::<Function>(m, key),
        Kind::Representation => of::<Representation>(m, key),
        Kind::Connection => of::<Connection>(m, key),
        Kind::Junction => of::<Junction>(m, key),
        Kind::Conductor => of::<Conductor>(m, key),
        Kind::PotentialDef => of::<PotentialDef>(m, key),
        Kind::Bond => of::<Bond>(m, key),
        Kind::ReportBlock => of::<ReportBlock>(m, key),
        Kind::Project => Some(m.project_row().changed_at()),
        // A delete plan may remove a library copy once its last referrer is gone.
        Kind::Part => of::<LibCopy<ew_schema::Part>>(m, key),
        Kind::Symbol => of::<LibCopy<ew_schema::SymbolDef>>(m, key),
        Kind::Fndef => of::<LibCopy<ew_schema::FnDef>>(m, key),
        Kind::Form => of::<LibCopy<ew_schema::FormDef>>(m, key),
        other => panic!("the generator never touches {other:?}"),
    }
}

// ---------------------------------------------------------------------------------------------------------
// Properties

proptest! {
    #![proptest_config(ProptestConfig { cases: 64, ..ProptestConfig::default() })]

    /// Doc 18 §3.3 `undo(all) ∘ apply(cmds) = id`: the inverse batch restores every row and index entry,
    /// and stamps every row it touches with its own revision.
    #[test]
    fn apply_then_inverse_restores_everything(actions in batch()) {
        let m0 = mini_golden();
        let mut counter = 0;
        let ops = interpret(&m0, &actions, &mut counter);
        let r = m0.rev().next();
        let m1 = m0.apply(&ops, r).expect("an interpreted batch applies in one transaction");
        let undo = r.next();
        let m2 = m1.apply(&invert_batch(&ops), undo).expect("the inverse batch applies");
        prop_assert!(m2.content_eq(&m0));
        for op in &ops {
            let key = op.key();
            if let Some(stamp) = changed_at(&m2, &key) {
                prop_assert_eq!(stamp, undo, "{:?} keeps a stale changed_at", key);
            } else {
                prop_assert!(m0.row(&key).is_none(), "{:?} vanished", key);
            }
            prop_assert_eq!(m2.row(&key).is_some(), m0.row(&key).is_some());
        }
    }

    /// ARCH §4.1 rebuilt = maintained: after every batch the delta-maintained base indexes equal the ones
    /// rebuilt from the tables.
    #[test]
    fn incremental_indexes_equal_rebuilt_after_every_batch(
        batches in prop::collection::vec(batch(), 1..=5),
    ) {
        let mut m = mini_golden();
        let mut counter = 0;
        for actions in &batches {
            m = step(&m, actions, &mut counter).0;
            prop_assert!(BaseIndexes::rebuild(&m).same_entries(m.indexes()));
        }
    }

    /// Doc 18 §3.3 `undo(all) ∘ apply(cmds) = id`, over a sequence: undoing the batches in reverse order
    /// (each as a new revision) restores the start.
    #[test]
    fn undo_of_a_sequence_restores_the_start(batches in prop::collection::vec(batch(), 1..=4)) {
        let start = mini_golden();
        let mut m = start.clone();
        let mut counter = 0;
        let mut applied = Vec::new();
        for actions in &batches {
            let (next, ops) = step(&m, actions, &mut counter);
            m = next;
            applied.push(ops);
        }
        for ops in applied.iter().rev() {
            m = m
                .apply(&invert_batch(ops), m.rev().next())
                .expect("the inverse batches apply in reverse order");
        }
        prop_assert!(m.content_eq(&start));
    }

    /// NFR-REL-07 order independence: the order of the records and library documents on load, unknown
    /// records included, changes neither the model nor its canonical content.
    #[test]
    fn from_records_is_order_independent(
        (records, lib) in (
            Just(records_with_unknowns()).prop_shuffle(),
            Just(mini_golden_parts().2).prop_shuffle(),
        ),
    ) {
        let (project, plain, plain_lib) = mini_golden_parts();
        let mut expected = plain;
        expected.extend(unknown_records());
        let reference = Model::from_records(project.clone(), expected, plain_lib)
            .expect("the fixture with unknown records loads");
        let shuffled = Model::from_records(project, records, lib).expect("a shuffled load succeeds");
        prop_assert!(shuffled.content_eq(&reference));
        prop_assert_eq!(digest(&shuffled), digest(&reference));
    }
}

fn unknown_records() -> Vec<Record> {
    vec![
        Record::Unknown(json!({"$k": "channel", "id": "0190aaaa-0000-7000-8000-000000000001"})),
        Record::Unknown(json!({"$k": "channel", "id": "0190aaaa-0000-7000-8000-000000000002"})),
    ]
}

fn records_with_unknowns() -> Vec<Record> {
    let mut records = mini_golden_parts().1;
    records.extend(unknown_records());
    records
}

/// Every row of every table as `"{kind}<TAB>{id}<TAB>{json}"` in kind then ID order, then the unknown records.
fn digest(m: &Model) -> Vec<String> {
    let mut out = Vec::new();
    macro_rules! lines {
        ($($t:ty),* $(,)?) => {$(
            for (id, record) in m.table::<$t>().iter() {
                let json = serde_json::to_string(&**record).expect("records serialise");
                out.push(format!("{:?}	{id}	{json}", <$t as Entity>::KIND));
            }
        )*};
    }
    lines!(
        ImportLineage,
        StructureNode,
        Section,
        ExternalRef,
        Page,
        Device,
        Function,
        Representation,
        Connection,
        Junction,
        Conductor,
        PotentialDef,
        Bond,
        ReportBlock,
        LibCopy<ew_schema::Part>,
        LibCopy<ew_schema::SymbolDef>,
        LibCopy<ew_schema::FnDef>,
        LibCopy<ew_schema::FormDef>,
    );
    for record in m.unknown_records() {
        out.push(serde_json::to_string(record).expect("records serialise"));
    }
    out
}

/// The generator reaches every action, and a delete can cascade.
#[test]
fn generator_produces_nontrivial_batches() {
    let m = mini_golden();
    let mut counter = 0;
    let plan = [
        Action::AddStructureNode(0),
        Action::AddDeviceWithMain(0),
        Action::AddAuxFunction(0),
        Action::AddConnection(0, 1, 0, 0),
        Action::AddConductor(0),
        Action::TouchDevice(0),
        Action::TouchConnectionRoute(0),
    ];
    let ops = interpret(&m, &plan, &mut counter);
    assert!(!ops.is_empty());
    let kinds: Vec<Kind> = ops.iter().map(|op| op.key().0).collect();
    for kind in [
        Kind::StructureNode,
        Kind::Device,
        Kind::Function,
        Kind::Connection,
        Kind::Conductor,
    ] {
        assert!(kinds.contains(&kind), "no op of kind {kind:?}: {kinds:?}");
    }
    let touched_device = ops
        .iter()
        .any(|op| op.before().is_some() && op.after().is_some() && op.key().0 == Kind::Device);
    assert!(touched_device, "TouchDevice produced no update");

    let keys = table_keys(&m);
    let longest = (0..keys.len())
        .map(|i| action_ops(&m, Action::DeleteViaPlan(i as u32), &mut counter).len())
        .max()
        .unwrap_or(0);
    assert!(longest > 1, "no delete cascaded");
}
